begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table p0_project_result(data jsonb);
grant all on p0_project_result to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"project_engineer"}}',true);
insert into p0_project_result select public.v1_create_project('{"project_ref":"P0-PROJECT-OUTCOME-PROOF","name":"P0 outcome proof","parties":{},"buildings":[{"code":"main","name":"Main"}],"initial_members":[],"attachments":[]}'::jsonb,'a1500000-0000-4000-8000-000000000501');
select is(public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->>'status','confirmed','Original creator can witness the committed create');
select is(public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->'response'->'project'->>'id',(select data->'project'->>'id' from p0_project_result),'Witness returns the actual authorized project');
select is(public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000599')->>'status','unknown','A missing witness remains unknown');
select ok(not (public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->'response' ? 'attachments'),'Historical attachment evidence is not replayed into a new authority context');
select throws_ok($$select public.v1_get_project_setup_command_outcome('v1_dispatch_materials','a1500000-0000-4000-8000-000000000501')$$,'22023','V1_PROJECT_COMMAND_OUTCOME_INVALID','Only the project command allowlist is accepted');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","app_metadata":{"role":"site_engineer"}}',true);
select is(public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->>'status','unknown','A Site Engineer cannot discover another actor receipt');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated","app_metadata":{"role":"procurement"}}',true);
select is(public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->>'status','unknown','Procurement cannot discover another actor receipt');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated","app_metadata":{"role":"admin"}}',true);
select is(public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->>'status','unknown','Admin oversight does not expose another actor command receipt');
set local role postgres;
create temporary table p0_effect_counts as select (select count(*) from public.v1_projects) projects,(select count(*) from public.v1_audit_events) audits,(select count(*) from public.v1_idempotency_keys) commands;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","app_metadata":{"role":"project_engineer"}}',true);
select public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->>'status';
select public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')->>'status';
set local role postgres;
select is((select count(*) from public.v1_projects),(select projects from p0_effect_counts),'Repeated read-only lookup creates no project');
select is((select count(*) from public.v1_audit_events),(select audits from p0_effect_counts),'Repeated read-only lookup creates no audit event');
select is((select count(*) from public.v1_idempotency_keys),(select commands from p0_effect_counts),'Repeated lookup creates no command');
update public.v1_profiles set is_active=false where auth_user_id='10000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.v1_get_project_setup_command_outcome('v1_create_project','a1500000-0000-4000-8000-000000000501')$$,'42501','V1_AUTHENTICATED_ROLE_REQUIRED','Deactivated actor cannot recover protected project data with an old claim');
set local role postgres;
select ok(not has_function_privilege('anon','public.v1_get_project_setup_command_outcome(text,uuid)','execute'),'Anonymous cannot call project outcome lookup');
select * from finish();
rollback;
